'use strict';

function validateAccessRequest(input) {
  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
    throw new TypeError('input must be an object');
  }

  const fields = ['displayName', 'department', 'location', 'phone', 'email', 'pin', 'pinConfirmation'];
  const values = {};
  const errors = {};

  for (const field of fields) {
    values[field] = typeof input[field] === 'string' ? input[field].trim() : '';
    if (values[field] === '') {
      errors[field] = 'required';
    }
  }

  if (values.phone && !/[0-9]{10}/.test(values.phone)) {
    errors.phone = 'invalid phone';
  }
  if (values.email && !/^[^@\s]+@[^@\s]+$/.test(values.email)) {
    errors.email = 'invalid email';
  }
  if (values.pin && (Array.from(values.pin).length !== 6 || !/[A-Za-z]/.test(values.pin) || !/[0-9]/.test(values.pin))) {
    errors.pin = 'invalid pin';
  }
  if (values.pinConfirmation && values.pinConfirmation !== values.pin) {
    errors.pinConfirmation = 'does not match';
  }

  const ok = Object.keys(errors).length === 0;
  const value = ok ? {
    displayName: values.displayName,
    department: values.department,
    location: values.location,
    phone: values.phone,
    email: values.email,
    pin: values.pin
  } : null;

  return { ok, errors, value };
}

module.exports = { validateAccessRequest };

