'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['validateAccessRequest']);
const { validateAccessRequest } = api;
assert.strictEqual(typeof validateAccessRequest, 'function');

const input = Object.freeze({
  displayName: '  Ada Lovelace  ',
  department: '\tEngineering\n',
  location: ' London ',
  phone: '0123456789',
  email: ' ada@example.com ',
  pin: ' A1-$xy ',
  pinConfirmation: '\tA1-$xy\n'
});
const valid = validateAccessRequest(input);
assert.deepStrictEqual(valid, {
  ok: true,
  errors: {},
  value: {
    displayName: 'Ada Lovelace',
    department: 'Engineering',
    location: 'London',
    phone: '0123456789',
    email: 'ada@example.com',
    pin: 'A1-$xy'
  }
});
assert.notStrictEqual(valid.value, input);
assert.strictEqual(Object.hasOwn(valid.value, 'pinConfirmation'), false);
assert.deepStrictEqual(input, {
  displayName: '  Ada Lovelace  ', department: '\tEngineering\n', location: ' London ',
  phone: '0123456789', email: ' ada@example.com ', pin: ' A1-$xy ', pinConfirmation: '\tA1-$xy\n'
});

const invalid = validateAccessRequest({
  displayName: ' ',
  department: 42,
  location: 'HQ',
  phone: '１２３４５６７８９０',
  email: 'a@@example.com',
  pin: 'abcdef',
  pinConfirmation: 'different'
});
assert.strictEqual(invalid.ok, false);
assert.strictEqual(invalid.value, null);
assert.deepStrictEqual(invalid.errors, {
  displayName: 'required',
  department: 'required',
  phone: 'invalid phone',
  email: 'invalid email',
  pin: 'invalid pin',
  pinConfirmation: 'does not match'
});
assert.deepStrictEqual(Object.keys(invalid.errors), ['displayName', 'department', 'phone', 'email', 'pin', 'pinConfirmation']);

const missing = validateAccessRequest({});
assert.strictEqual(missing.ok, false);
assert.strictEqual(missing.value, null);
assert.deepStrictEqual(missing.errors, {
  displayName: 'required',
  department: 'required',
  location: 'required',
  phone: 'required',
  email: 'required',
  pin: 'required',
  pinConfirmation: 'required'
});

for (const email of ['a b@example.com', '@example.com', 'a@', 'a@b@c']) {
  const candidate = { ...input, email };
  assert.strictEqual(validateAccessRequest(candidate).errors.email, 'invalid email');
}
for (const phone of ['123456789', '12345678901', '12345x7890']) {
  const candidate = { ...input, phone };
  assert.strictEqual(validateAccessRequest(candidate).errors.phone, 'invalid phone');
}
for (const pin of ['A1234', 'A123456', '123456', 'ABCDEF', 'Ａ12345']) {
  const candidate = { ...input, pin, pinConfirmation: pin };
  assert.strictEqual(validateAccessRequest(candidate).errors.pin, 'invalid pin');
}

for (const badInput of [null, undefined, [], 'x', 1, true]) {
  assert.throws(() => validateAccessRequest(badInput), TypeError);
}

